        let mut m = self.keys.lock().unwrap();
        match m.find(key) {
            Some(ref v) => Some(v),
            None => None,
        }
    }

    // Delete a key-value pair
    pub fn delete(&mut self, key: &str) {
        let mut m = self.keys.lock().unwrap();
        m.remove(key);
    }
}
