import 'dart:io';

// Function to slice an image into bytes
Future<List<int>> sliceImageToBytes(String imageUrl) async {
  final File file = await File(imageUrl);
  final byte[] data = await file.readAll();

  // Convert bytes array to string
  String imageData = String.fromIterable(data);

