It seems like your program is not working because the sorting operation has been performed before inserting the elements into the BST. This means that the BST will be empty after insertion.

The correct approach would be to perform both operations in one step:

1. Insert all elements into the BST.
2. Sort the BST.

Here is an updated version of your code which performs these steps in sequence:

```cpp
#include <iostream>
#include <vector>

struct Node {
    int key;
    Node* left;
    Node* right;

    Node(int key): key(key), left(nullptr), right(nullptr) {}
};

class BST {
private:
    Node* root;

public:
    BST(): root(nullptr) {}

    void insert(int key) {
        root = insert(root, key);
    }

    Node* insert(Node* node, int key) {
        if (node == nullptr) {
            return new Node(key);
        }

        if (key < node->key) {
            node->left = insert(node->left, key);
        } else {
            node->right = insert(node->right, key);
        }

        return node;
    }

    void selectionSort(std::vector<int>& data) {
        for (size_t i = 0; i < data.size(); ++i) {
            size_t minIndex = i;
            for (size_t j = i + 1; j < data.size(); ++j) {
                if (data[j] < data[minIndex]) {
                    minIndex = j;
                }
            }
            std::swap(data[i], data[minIndex]);
        }
    }

    void printTree(Node* node) {
        if (node != nullptr) {
            printTree(node->left);
            std::cout << node->key << " ";
            printTree(node->right);
        }
    }

    void printBST(Node* node) {
        if (node != nullptr) {
            printBST(node->left);
            std::cout << node->key << " ";
            printBST(node->right);
        }
    }

    void buildBST(std::vector<int>& data) {
        selectionSort(data);

        Node* newNode = nullptr;
        Node* current = nullptr;
        for (int value : data) {
            if (newNode == nullptr || value > newNode->key) {
                newNode = new Node(value);
            }
            current = newNode;
            newNode = insert(current, value);
        }

        printBST(current);
    }

    ~BST() {
        delete root;
    }
};
```

In this revised code, we have added two functions `selectionSort` and `printTree`. These functions are used to sort the data and print the nodes of the BST respectively. We also added a function `buildBST`, which uses the `selectionSort` function to sort the data and calls `printTree` to print the nodes of the BST. Finally, the destructor `~BST()` deletes the root node of the BST. 

