Here is an example C++ code for creating neurons using the Izhikevich model:

```cpp
#include <iostream>
#include <vector>

class Neuron {
public:
    double rate;
    std::vector<double> inputs;
    std::vector<double> outputs;

    Neuron(double rate) : rate(rate), inputs(), outputs() {}

    void setRate(double rate) { this->rate = rate; }

    void addInput(double value) { inputs.push_back(value); }
    void removeInput(int index) { inputs.erase(inputs.begin() + index); }

    void addOutput(double value) { outputs.push_back(value); }
    void removeOutput(int index) { outputs.erase(outputs.begin() + index); }

    void updateState() {
        if (inputs.size() == 0 || outputs.size() == 0)
            return;

        double sum = 0;
        for (int i = 0; i < inputs.size(); ++i) {
            sum += inputs[i];
        }

        double delta = -sum * rate / inputs.size();
        for (int i = 0; i < outputs.size(); ++i) {
            outputs[i] -= delta;
        }
    }

private:
    void resetState() {
        inputs.clear();
        outputs.clear();
    }
};

class Network {
public:
    Network(std::vector<Neuron>& neurons);

    void addNeuron(Neuron* neuron);
    void removeNeuron(Neuron* neuron);

    void connectToNeuron(Neuron* neuron1, Neuron* neuron2);
    void disconnectFromNeuron(Neuron* neuron1, Neuron* neuron2);

    void simulateSimulation();

private:
    std::vector<Neuron*> neurons;
};

void Network::addNeuron(Neuron* neuron) {
    neurons.push_back(neuron);
}

void Network::removeNeuron(Neuron* neuron) {
    neurons.erase(neurons.find(neuron));
}

void Network::connectToNeuron(Neuron* neuron1, Neuron* neuron2) {
    if (neuron1 != nullptr && neuron2 != nullptr) {
        if (neuron1->getInputs().size() > 0 &&
                neuron2->getOutputs().size() > 0) {
            int index1 = neuron1->getInputs().find(neuron1->getInputs()[0]);
            int index2 = neuron2->getOutputs().find(neuron2->getOutputs()[0]);

            if (index1 != neuron1->getInputs().end() &&
                    index2 != neuron2->getOutputs().end()) {
                neurons[index1]->setRate(
                        neuron1->getRate() +
                        neuron2->getRate() *
                        (1 - neuron2->getRate() / neuron1->getRate()));
            } else {
                neurons[index1]->setRate(
                        neuron1->getRate());
            }
        }
    }
}

void Network::disconnectFromNeuron(Neuron* neuron1, Neuron* neuron2) {
    if (neuron1 != nullptr && neuron2 != nullptr) {
        if (neuron1->getInputs().size() > 0 &&
                neuron2->getOutputs().size() > 0) {
            int index1 = neuron1->getInputs().find(neuron1->getInputs()[0]);
            int index2 = neuron2->getOutputs().find(neuron2->getOutputs()[0]);

            if (index1 != neuron1->getInputs().end() &&
                    index2 != neuron2->getOutputs().end()) {
                neurons[index1]->setRate(
                        neuron1->getRate());
            }
        }
    }
}
```

