```csharp
using System;
using System.Collections.Generic;

public class Program
{
    public static void Main()
    {
        // Define two ranges
        var range1 = new Range(10, 20);
        var range2 = new Range(5, 15);

        // Find overlapping ranges
        List<Range> overlappingRanges = FindOverlappingRanges(range1, range2);

        Console.WriteLine("Overlapping ranges:");
        foreach (var range in overlappingRanges)
        {
            Console.WriteLine($"({range.StartIncl}, {range.EndExl})");
        }
    }

    private static List<Range> FindOverlappingRanges(Range range1, Range range2)
    {
        List<Range> overlappingRanges = new List<Range>();

        for (int i = Math.Min(range1.StartIncl, range2.StartIncl); i <= Math.Max(range1.EndExl, range2.EndExl); i++)
        {
            if (range1.StartIncl <= i && i <= range2.StartIncl || range1.EndExl >= i && i <= range2.EndExl)
            {
                overlappingRanges.Add(new Range(i, i));
            }
        }

        return overlappingRanges;
    }
}
```

This code defines two ranges `range1` and `range2`, then finds their overlapping ranges using a loop. It compares each element from the start of one range to the end of another range, checking if they overlap or not. If they do, it adds them to the list of overlapping ranges.

