    public float scale = 1f;
    private Vector3[] chunkData;
    private List<Vector3> chunkList;

    void Start() {
        chunkData = new Vector3[100000];
        chunkList = new List<Vector3>();

        // Generate random data points
        Random rand = new Random();
        for (int i = 0; i < 100000; i++) {
            int x = rand.Next(-scale * 20000, scale * 20000);
            int y = rand.Next(-scale * 20000, scale * 20000);
            chunkData[i] = new Vector3(x, y, 0);

            // Add to list of chunks
            chunkList.Add(chunkData[i]);
        }

        // Load all chunks into memory
        chunkData = chunkList.ToArray();
        chunkList.Clear();
    }

    void Update() {
        // Render all chunks
        foreach (var chunk in chunkData) {
            GameObject obj = Instantiate(chunk, transform.position, Quaternion.identity);
            obj.transform.parent = transform;
            obj.GetComponent<RenderTexture>().texture = Texture2D.LoadFromMemory(chunkData[(int)chunk.x][(int)chunk.y], 32);
        }
